//! Compiles `stencils/rows.rs` with the toolchain's own rustc for the build target, once per
//! shard, into objects. The rows `stencils/library.rs` lists are generated by `instances` (one
//! macro invocation each) and split by `stencils/shards.rs` into `OUT_DIR/instances_<i>.rs`;
//! every shard is the shared row definitions plus its own instances, compiled in parallel to bound
//! rustc's peak memory. Each object's functions and relocations are read (`build/elf.rs` for Linux
//! x86-64 and AArch64, `build/macho.rs` for macOS arm64) and the shards' rows are merged into one
//! sorted static table (`OUT_DIR/rustc_stencils.rs`).
//!
//! Extension point: a new row family adds its `*_row!` macro to `rows.rs` and a generator line
//! to `instances`; a new source file adds an entry to `SOURCES`. Sharding, per-shard checks and
//! the merge apply to both without further edits. A row that contains a `call` or a `ret` is a
//! build error: rows chain by `become` only, and only the `leave_*` rows return. Other targets
//! get an empty table.
#[path = "build/bytes.rs"]
mod bytes;
#[path = "src/class.rs"]
mod class;
#[path = "build/elf.rs"]
mod elf;
#[path = "stencils/library.rs"]
mod library;
#[path = "build/macho.rs"]
mod macho;
#[path = "stencils/shards.rs"]
mod shards;
#[path = "build/transfer.rs"]
mod transfer;

use bytes::{ObjectReloc, ObjectRow};
use class::{MOVW, MOVW_GROUPS, is_successor};
use std::{
    collections::BTreeMap,
    env, fs,
    path::{Path, PathBuf},
    process::Command,
    sync::atomic::{AtomicUsize, Ordering},
    thread,
};
use transfer::{Arch, check_no_return, check_transfer, check_value_field};

const SOURCE: &str = "stencils/rows.rs";
/// Environment variable of each rustc process naming its shard's instance file (`rows.rs` reads
/// it with `env!`).
const INSTANCES_VAR: &str = "QUENCH_STENCIL_INSTANCES";
/// The shard that also defines the fixed rows of the target's `stencils/entry*.rs` (cfg
/// `fixed_rows`), so no name is defined twice.
const FIXED_ROWS_SHARD: usize = 0;
const EXIT_PREFIX: usize = 4;
/// Successor hole indexes (`quench_bjit::NEXT`, `TAKEN`, `EXIT`).
const NEXT: u32 = 0;
const TAKEN: u32 = 1;
const EXIT_BASE: u32 = 2;

/// Every file whose change must recompile the stencils: the stencil sources and the runtime's
/// staged rows they include, and nothing else.
const SOURCES: [&str; 12] = [
    "stencils", "../quench-runtime/src/staged/stage.rs", "../quench-runtime/src/staged/value.rs",
    "../quench-runtime/src/staged/object.rs", "../quench-runtime/src/staged/elements.rs",
    "../quench-runtime/src/staged/environment.rs", "../quench-runtime/src/staged/entry.rs", "../quench-runtime/src/staged/frame.rs", "build.rs", "build", "src/class.rs", "src/numeric.rs",
];

/// The architecture and object reader of a build target, if its stencils are supported.
fn target() -> Option<(Arch, fn(&[u8]) -> Vec<ObjectRow>)> {
    let var = |name| env::var(name).unwrap_or_default();
    match (var("CARGO_CFG_TARGET_ARCH").as_str(), var("CARGO_CFG_TARGET_OS").as_str()) {
        ("x86_64", "linux") => Some((Arch::X86_64, elf::rows)),
        ("aarch64", "linux") => Some((Arch::Aarch64, elf::rows)),
        ("aarch64", "macos") => Some((Arch::Aarch64, macho::rows)),
        _ => None,
    }
}

fn main() {
    for source in SOURCES {
        println!("cargo::rerun-if-changed={source}");
    }
    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
    let table = out.join("rustc_stencils.rs");
    let Some((arch, read)) = target() else {
        fs::write(&table, "pub(crate) static RAW: &[RawStencil] = &[];\n").unwrap();
        return;
    };
    let instances = instances();
    let parts = shards::split(&instances);
    for (shard, part) in parts.iter().enumerate() {
        fs::write(instance_file(&out, shard), part.concat()).unwrap();
    }
    fs::write(&table, table_source(&shards::merge(compile_shards(&out, parts.len(), arch, read)))).unwrap();
}

/// One macro invocation per generated row, the unit `shards::split` distributes.
fn instances() -> Vec<String> {
    let numbers = library::library().into_iter().map(|c| format!("number_row!({}, {}, {}, {}, {}, {});\n", library::name(c), c.0, c.1, c.2, c.3, c.4));
    let heaps = library::heap_library().into_iter().map(|c| format!("heap_row!({}, {}, {}, {}, {}, {});\n", library::heap_name(c), c.0, c.1, c.2, c.3, c.4));
    numbers.chain(heaps).collect()
}

fn instance_file(out: &Path, shard: usize) -> PathBuf {
    out.join(format!("instances_{shard}.rs"))
}

/// Compiles every shard (at most `shards::workers` rustc processes at once) and reads each
/// object's rows.
fn compile_shards(out: &Path, count: usize, arch: Arch, read: fn(&[u8]) -> Vec<ObjectRow>) -> Vec<Vec<(String, String)>> {
    let parallelism = thread::available_parallelism().map_or(1, std::num::NonZero::get);
    let next = AtomicUsize::new(0);
    thread::scope(|scope| {
        let workers: Vec<_> = (0..shards::workers(count, parallelism))
            .map(|_| {
                scope.spawn(|| {
                    let mut done = Vec::new();
                    loop {
                        let shard = next.fetch_add(1, Ordering::Relaxed);
                        if shard >= count {
                            return done;
                        }
                        done.push(stencil_rows(arch, read(&fs::read(compile(out, shard)).unwrap())));
                    }
                })
            })
            .collect();
        workers.into_iter().flat_map(|worker| worker.join().expect("a shard worker")).collect()
    })
}

fn compile(out: &Path, shard: usize) -> PathBuf {
    let object = out.join(format!("rows_{shard}.o"));
    let mut command = Command::new(env::var_os("RUSTC").unwrap_or_else(|| "rustc".into()));
    command.args(["--target", &env::var("TARGET").expect("cargo sets TARGET"), "--edition", "2024", "--crate-type=lib", "--crate-name=quench_stencil_rows", "--emit=obj", "-C", "opt-level=3", "-C", "panic=abort", "-C", "relocation-model=static", "-C", "codegen-units=8", "-C", "debuginfo=0"]);
    command.args(["--check-cfg", "cfg(fixed_rows)"]);
    if shard == FIXED_ROWS_SHARD {
        command.args(["--cfg", "fixed_rows"]);
    }
    let status = command.env(INSTANCES_VAR, instance_file(out, shard)).arg("-o").arg(&object).arg(SOURCE).status().expect("run rustc");
    assert!(status.success(), "rustc failed on {SOURCE} (shard {shard})");
    object
}

/// The rows of one shard's object as (name, table entry), each checked.
fn stencil_rows(arch: Arch, rows: Vec<ObjectRow>) -> Vec<(String, String)> {
    rows.iter()
        .map(|row| {
            check_no_return(arch, &row.name, &row.code);
            let relocs = relocations(arch, row);
            (row.name.clone(), format!("    RawStencil {{ name: {:?}, code: &{:?}, relocs: &{relocs:?} }},\n", row.name, row.code))
        })
        .collect()
}

/// The merged rows as the static table `RAW`.
fn table_source(rows: &[(String, String)]) -> String {
    let body: String = rows.iter().map(|(_, row)| row.as_str()).collect();
    format!("pub(crate) static RAW: &[RawStencil] = &[\n{body}];\n")
}

/// The relocations of one row as (offset, class, index, addend).
fn relocations(arch: Arch, row: &ObjectRow) -> Vec<(u16, u8, u8, i32)> {
    check_movw_groups(row);
    row.relocs
        .iter()
        .map(|reloc| {
            if is_successor(reloc.class) {
                check_transfer(arch, &row.name, &row.code, reloc.offset, reloc.class);
            }
            check_value_field(&row.name, &row.code, reloc.offset, reloc.class);
            let index = hole_index(&row.name, &reloc.symbol, reloc.class);
            (u16::try_from(reloc.offset).expect("a stencil under 64 KiB"), reloc.class, u8::try_from(index).expect("a small hole index"), i32::try_from(reloc.addend).expect("a small addend"))
        })
        .collect()
}

/// A 64-bit value hole is patched in four 16-bit groups: every hole the row names has all four,
/// the same number of times, or a patch would leave part of its value as the object's zeros.
fn check_movw_groups(row: &ObjectRow) {
    let mut groups: BTreeMap<&str, [usize; MOVW_GROUPS as usize]> = BTreeMap::new();
    for ObjectReloc { symbol, class, .. } in row.relocs.iter().filter(|r| r.class >= MOVW) {
        groups.entry(symbol).or_default()[usize::from(class - MOVW)] += 1;
    }
    for (symbol, counts) in groups {
        assert!(counts.iter().all(|n| *n == counts[0]), "stencil {}: hole {symbol} lacks a movz/movk group: {counts:?}", row.name);
    }
}

/// The hole index of a relocation. Value hole `HOLE_V<n>` is index n; `HOLE_NEXT` 0, `HOLE_TAKEN` 1,
/// `HOLE_EXIT<k>` 2 + k (the successor indexes of `quench_bjit`).
fn hole_index(row: &str, symbol: &str, class: u8) -> u32 {
    let rest = symbol.strip_prefix("HOLE_").unwrap_or_else(|| panic!("stencil {row}: relocation against {symbol}, not a hole"));
    let number = |digits: &str| digits.parse::<u32>().unwrap_or_else(|_| panic!("stencil {row}: bad hole {symbol}"));
    match (is_successor(class), rest) {
        (true, "NEXT") => NEXT,
        (true, "TAKEN") => TAKEN,
        (true, exit) if exit.starts_with("EXIT") => EXIT_BASE + number(&exit[EXIT_PREFIX..]),
        (false, value) if value.starts_with('V') => number(&value[1..]),
        _ => panic!("stencil {row}: hole {symbol} used in the wrong way"),
    }
}
